function transition(dir){
  if(animating) return;
  animating=true;
  const stage=document.getElementById('stage');
  const old=stage.querySelector('.screen');
  const nw=document.createElement('div');
  nw.className='screen '+(dir>0?'in-fwd':'in-back');
  nw.innerHTML=screenHTML(T[L]);
  if(old){ old.classList.remove('in-fwd','in-back'); old.classList.add(dir>0?'out-fwd':'out-back'); }
  stage.appendChild(nw);
  paintChrome();
  setTimeout(()=>{ if(old&&old.parentNode) old.parentNode.removeChild(old); animating=false; },380);
}
function go(d){
